import { useMemo, useState } from "react";
import {
  Check,
  CheckCircle2,
  Circle,
  ListTodo,
  Plus,
  Sparkles,
  Trash2,
  X,
} from "lucide-react";

type Filter = "all" | "active" | "completed";

type Task = {
  id: string;
  text: string;
  completed: boolean;
  createdAt: number;
};

const FILTERS: { key: Filter; label: string }[] = [
  { key: "all", label: "All" },
  { key: "active", label: "Active" },
  { key: "completed", label: "Completed" },
];

export default function App() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [input, setInput] = useState("");
  const [filter, setFilter] = useState<Filter>("all");

  const addTask = () => {
    const text = input.trim();
    if (!text) return;
    setTasks((prev) => [
      ...prev,
      {
        id:
          typeof crypto !== "undefined" && "randomUUID" in crypto
            ? crypto.randomUUID()
            : `${Date.now()}-${Math.random().toString(16).slice(2)}`,
        text,
        completed: false,
        createdAt: Date.now(),
      },
    ]);
    setInput("");
  };

  const toggleTask = (id: string) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
  };

  const deleteTask = (id: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  const clearCompleted = () => {
    setTasks((prev) => prev.filter((t) => !t.completed));
  };

  const remaining = tasks.filter((t) => !t.completed).length;
  const completedCount = tasks.length - remaining;
  const progress = tasks.length ? (completedCount / tasks.length) * 100 : 0;

  const counts = useMemo(
    () => ({
      all: tasks.length,
      active: remaining,
      completed: completedCount,
    }),
    [tasks.length, remaining, completedCount]
  );

  const visible = tasks.filter((t) => {
    if (filter === "active") return !t.completed;
    if (filter === "completed") return t.completed;
    return true;
  });

  return (
    <div className="min-h-screen bg-gradient-to-br from-indigo-50 via-slate-50 to-sky-100 px-4 py-12 text-slate-900">
      <div className="mx-auto w-full max-w-xl">
        <header className="mb-6 flex items-start justify-between gap-4">
          <div>
            <div className="flex items-center gap-2">
              <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-indigo-600 text-white shadow-lg shadow-indigo-200">
                <ListTodo className="h-5 w-5" />
              </span>
              <h1 className="text-3xl font-bold tracking-tight">My Tasks</h1>
            </div>
            <p className="mt-2 flex items-center gap-1.5 text-sm text-slate-500">
              <Sparkles className="h-4 w-4 text-indigo-400" />
              {remaining} {remaining === 1 ? "task" : "tasks"} left
              {completedCount > 0 && (
                <span className="text-slate-400">
                  · {completedCount} done
                </span>
              )}
            </p>
          </div>
          <div className="hidden rounded-xl bg-white/70 px-4 py-2 text-right shadow-sm ring-1 ring-slate-200/60 sm:block">
            <p className="text-2xl font-bold tabular-nums text-indigo-600">
              {Math.round(progress)}%
            </p>
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              complete
            </p>
          </div>
        </header>

        <div className="rounded-2xl bg-white/90 p-5 shadow-xl shadow-slate-200/60 ring-1 ring-slate-200/70 backdrop-blur">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <input
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") addTask();
                }}
                placeholder="What needs to be done?"
                aria-label="New task"
                className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 pr-8 text-sm outline-none transition placeholder:text-slate-400 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
              />
              {input && (
                <button
                  onClick={() => setInput("")}
                  aria-label="Clear input"
                  className="absolute right-2 top-1/2 -translate-y-1/2 rounded p-0.5 text-slate-400 transition hover:text-slate-600"
                >
                  <X className="h-4 w-4" />
                </button>
              )}
            </div>
            <button
              onClick={addTask}
              disabled={!input.trim()}
              className="flex items-center gap-1.5 rounded-lg bg-indigo-600 px-4 py-2.5 text-sm font-medium text-white shadow-sm transition hover:bg-indigo-700 active:scale-95 disabled:cursor-not-allowed disabled:opacity-40"
            >
              <Plus className="h-4 w-4" />
              Add
            </button>
          </div>

          <div className="mt-4">
            <div className="h-1.5 w-full overflow-hidden rounded-full bg-slate-100">
              <div
                className="h-full rounded-full bg-gradient-to-r from-indigo-500 to-sky-400 transition-all duration-500"
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>

          <div className="mt-4 flex gap-1 rounded-lg bg-slate-100 p-1">
            {FILTERS.map((f) => (
              <button
                key={f.key}
                onClick={() => setFilter(f.key)}
                className={`flex flex-1 items-center justify-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition ${
                  filter === f.key
                    ? "bg-white text-indigo-600 shadow-sm"
                    : "text-slate-500 hover:text-slate-700"
                }`}
              >
                {f.label}
                <span
                  className={`rounded-full px-1.5 py-0.5 text-[11px] tabular-nums ${
                    filter === f.key
                      ? "bg-indigo-50 text-indigo-500"
                      : "bg-slate-200/70 text-slate-500"
                  }`}
                >
                  {counts[f.key]}
                </span>
              </button>
            ))}
          </div>

          <ul className="mt-4 space-y-2">
            {visible.length === 0 && (
              <li className="flex flex-col items-center gap-2 py-10 text-center">
                <CheckCircle2 className="h-8 w-8 text-slate-300" />
                <p className="text-sm text-slate-400">
                  {tasks.length === 0
                    ? "Nothing here yet — add your first task above."
                    : filter === "active"
                    ? "All tasks are complete. Nice work!"
                    : filter === "completed"
                    ? "No completed tasks yet."
                    : "No tasks here yet."}
                </p>
              </li>
            )}
            {visible.map((task) => (
              <li
                key={task.id}
                className="group flex items-center gap-3 rounded-lg border border-slate-200 bg-white px-3 py-2.5 transition hover:border-slate-300 hover:bg-slate-50/80"
              >
                <button
                  onClick={() => toggleTask(task.id)}
                  aria-label={
                    task.completed ? "Mark task active" : "Mark task complete"
                  }
                  className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border transition ${
                    task.completed
                      ? "border-indigo-600 bg-indigo-600 text-white"
                      : "border-slate-300 text-transparent hover:border-indigo-400"
                  }`}
                >
                  <Check className="h-3 w-3" strokeWidth={3} />
                </button>
                <span
                  className={`flex-1 break-words text-sm transition ${
                    task.completed
                      ? "text-slate-400 line-through"
                      : "text-slate-700"
                  }`}
                >
                  {task.text}
                </span>
                <button
                  onClick={() => deleteTask(task.id)}
                  className="rounded p-1 text-slate-300 opacity-0 transition hover:bg-rose-50 hover:text-rose-600 focus:opacity-100 group-hover:opacity-100"
                  aria-label="Delete task"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </li>
            ))}
          </ul>

          <div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3 text-xs text-slate-400">
            <span className="flex items-center gap-1.5">
              <Circle className="h-3 w-3" />
              {tasks.length} {tasks.length === 1 ? "task" : "tasks"} total
            </span>
            <button
              onClick={clearCompleted}
              disabled={completedCount === 0}
