            </div>
            <div>
              <h1 className="text-lg font-bold tracking-tight sm:text-xl">Unit Converter</h1>
              <p className="text-xs text-slate-400">Length · Weight · Temperature</p>
            </div>
          </div>
          <div className="hidden items-center gap-1.5 rounded-full border border-white/10 bg-white/[0.04] px-3 py-1.5 text-xs text-slate-400 sm:flex">
            <Sparkles className="h-3.5 w-3.5 text-cyan-300" />
            Live conversion
          </div>
        </header>

        <div className="rounded-3xl border border-white/10 bg-white/[0.04] p-4 shadow-2xl shadow-black/40 backdrop-blur-xl sm:p-6">
          <div className="flex rounded-2xl border border-white/10 bg-slate-900/40 p-1">
            {CATEGORIES.map((item) => {
              const Icon = item.icon;
              const active = item.id === category.id;
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => selectCategory(item)}
                  aria-pressed={active}
                  className={`group relative flex flex-1 items-center justify-center gap-2 rounded-xl px-2 py-2.5 text-sm font-semibold transition sm:px-3 ${
                    active
                      ? "bg-white/[0.09] text-white shadow-sm ring-1 ring-white/15"
                      : "text-slate-400 hover:text-slate-200"
                  }`}
                >
                  <Icon
                    className={`h-4 w-4 transition ${
                      active ? "text-white" : "text-slate-500 group-hover:text-slate-300"
                    }`}
                  />
                  <span>{item.label}</span>
                  {active && (
                    <span
                      className={`absolute inset-x-3 -bottom-px h-px bg-gradient-to-r ${item.accent}`}
                    />
                  )}
                </button>
              );
            })}
          </div>

          <div className="mt-5 grid gap-3 sm:grid-cols-[1fr_auto_1fr] sm:items-center">
            <div className="rounded-2xl border border-white/10 bg-slate-900/45 p-3.5">
              <div className="mb-3 flex items-center justify-between">
                <span className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">
                  From
