                <span className="text-xs text-slate-500">{fromUnit.symbol}</span>
              </div>
              <UnitSelect
                units={category.units}
                value={fromUnit.id}
                onChange={setFromId}
                align="left"
              />
              <div className="mt-3 flex items-center gap-2">
                <input
                  value={input}
                  onChange={(event) => handleInput(event.target.value)}
