                  className="w-full min-w-0 bg-transparent text-3xl font-bold tracking-tight text-white outline-none placeholder:text-slate-600 sm:text-4xl"
                />
                <span className="shrink-0 text-sm font-semibold text-slate-400">
                  {fromUnit.symbol}
