              >
                <ArrowDownUp
                  className="h-4.5 w-4.5 transition-transform duration-500 sm:h-5 sm:w-5"
                  style={{ transform: `rotate(${spin * 180}deg)` }}
                  strokeWidth={2.5}
                />
              </button>
            </div>

            <div className="rounded-2xl border border-white/10 bg-slate-900/45 p-3.5">
              <div className="mb-3 flex items-center justify-between">
                <span className="text-[11px] font-semibold uppercase tracking-[0.14em] text-slate-500">
                  To
                </span>
                <span className="text-xs text-slate-500">{toUnit.symbol}</span>
              </div>
              <UnitSelect
                units={category.units}
                value={toUnit.id}
                onChange={setToId}
                align="right"
              />
              <div className="mt-3 flex items-center gap-2">
                <div
                  title={result !== null ? `${result} ${toUnit.symbol}` : undefined}
                  className="w-full min-w-0 truncate bg-gradient-to-r from-cyan-300 via-indigo-300 to-fuchsia-300 bg-clip-text text-3xl font-bold tracking-tight text-transparent sm:text-4xl"
