              disabled={history.length === 0}
              className="flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs font-medium text-slate-500 transition hover:bg-white/[0.06] hover:text-slate-200 disabled:cursor-not-allowed disabled:opacity-40"
            >
              <Trash2 className="h-3.5 w-3.5" />
              Clear
            </button>
          </div>

          {history.length === 0 ? (
            <div className="mt-3 flex flex-col items-center justify-center gap-1.5 rounded-2xl border border-dashed border-white/10 px-4 py-6 text-center">
              <p className="text-sm font-medium text-slate-400">No conversions yet</p>
              <p className="text-xs text-slate-500">
                Type a value — your last five conversions show up here.
              </p>
            </div>
          ) : (
            <ul className="mt-3 space-y-1.5">
              {history.map((entry) => {
                const info = CATEGORIES.find((item) => item.id === entry.category);
                const Icon = info?.icon ?? Ruler;
                return (
                  <li key={entry.id}>
                    <button
                      type="button"
                      onClick={() => {
                        if (!info) return;
                        setCategoryId(info.id);
                        setFromId(entry.from.id);
                        setToId(entry.to.id);
                        setInput(rawNumber(entry.input));
                        setCopied(false);
                      }}
                      className="group flex w-full items-center gap-3 rounded-2xl border border-white/[0.06] bg-slate-900/40 px-3 py-2.5 text-left transition hover:border-white/15 hover:bg-slate-900/70"
                    >
                      <span
                        className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-xl ring-1 ${
                          info?.soft ?? "bg-white/10 text-slate-300 ring-white/10"
                        }`}
                      >
                        <Icon className="h-4 w-4" />
                      </span>
                      <span className="min-w-0 flex-1">
                        <span className="block truncate text-sm font-semibold text-slate-200">
                          {formatNumber(entry.input)} {entry.from.symbol}
                          <span className="mx-1.5 text-slate-500">=</span>
                          <span className="text-white">{formatNumber(entry.output)}</span>{" "}
                          {entry.to.symbol}
                        </span>
                        <span className="mt-0.5 flex items-center gap-1.5 text-[11px] text-slate-500">
                          {info?.label}
                          <span className="h-0.5 w-0.5 rounded-full bg-slate-600" />
                          {new Date(entry.at).toLocaleTimeString("en-US", {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </span>
                      </span>
                      <span className="shrink-0 text-[11px] text-slate-600 transition group-hover:text-slate-400">
                        Restore
                      </span>
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        <p className="mt-5 text-center text-[11px] text-slate-600">
          Conversions update as you type · history keeps the last five
        </p>
      </div>
    </div>
  );
}
"}

