import { useEffect, useMemo, useRef, useState } from "react";
import {
  ArrowDownUp,
  Check,
  ChevronDown,
  Copy,
  History,
  Ruler,
  Scale,
  Sparkles,
  Thermometer,
  Trash2,
} from "lucide-react";
import "@fontsource-variable/plus-jakarta-sans";

type CategoryId = "length" | "weight" | "temperature";

type Unit = {
  id: string;
  name: string;
  symbol: string;
  factor?: number;
};

type Category = {
  id: CategoryId;
  label: string;
  icon: typeof Ruler;
  units: Unit[];
  defaults: [string, string];
  accent: string;
  soft: string;
};

type HistoryEntry = {
  id: string;
  category: CategoryId;
  from: Unit;
  to: Unit;
  input: number;
  output: number;
  at: number;
};

const CATEGORIES: Category[] = [
  {
    id: "length",
    label: "Length",
    icon: Ruler,
    accent: "from-sky-400 to-indigo-500",
    soft: "bg-sky-400/15 text-sky-300 ring-sky-400/30",
    defaults: ["meter", "foot"],
    units: [
      { id: "meter", name: "Meter", symbol: "m", factor: 1 },
      { id: "kilometer", name: "Kilometer", symbol: "km", factor: 1000 },
      { id: "centimeter", name: "Centimeter", symbol: "cm", factor: 0.01 },
      { id: "millimeter", name: "Millimeter", symbol: "mm", factor: 0.001 },
      { id: "mile", name: "Mile", symbol: "mi", factor: 1609.344 },
      { id: "yard", name: "Yard", symbol: "yd", factor: 0.9144 },
      { id: "foot", name: "Foot", symbol: "ft", factor: 0.3048 },
      { id: "inch", name: "Inch", symbol: "in", factor: 0.0254 },
      { id: "nautical-mile", name: "Nautical mile", symbol: "nmi", factor: 1852 },
    ],
  },
  {
    id: "weight",
    label: "Weight",
    icon: Scale,
    accent: "from-amber-400 to-orange-500",
    soft: "bg-amber-400/15 text-amber-300 ring-amber-400/30",
    defaults: ["kilogram", "pound"],
    units: [
      { id: "kilogram", name: "Kilogram", symbol: "kg", factor: 1 },
      { id: "gram", name: "Gram", symbol: "g", factor: 0.001 },
      { id: "milligram", name: "Milligram", symbol: "mg", factor: 0.000001 },
      { id: "tonne", name: "Metric ton", symbol: "t", factor: 1000 },
      { id: "pound", name: "Pound", symbol: "lb", factor: 0.45359237 },
      { id: "ounce", name: "Ounce", symbol: "oz", factor: 0.028349523125 },
      { id: "stone", name: "Stone", symbol: "st", factor: 6.35029318 },
    ],
  },
  {
    id: "temperature",
    label: "Temperature",
    icon: Thermometer,
    accent: "from-rose-400 to-fuchsia-500",
    soft: "bg-rose-400/15 text-rose-300 ring-rose-400/30",
    defaults: ["celsius", "fahrenheit"],
    units: [
      { id: "celsius", name: "Celsius", symbol: "°C" },
      { id: "fahrenheit", name: "Fahrenheit", symbol: "°F" },
      { id: "kelvin", name: "Kelvin", symbol: "K" },
    ],
  },
];

function toCelsius(value: number, unitId: string): number {
  if (unitId === "fahrenheit") return (value - 32) * (5 / 9);
  if (unitId === "kelvin") return value - 273.15;
  return value;
}

function fromCelsius(value: number, unitId: string): number {
  if (unitId === "fahrenheit") return value * (9 / 5) + 32;
  if (unitId === "kelvin") return value + 273.15;
  return value;
}

function convert(value: number, category: Category, from: Unit, to: Unit): number {
  if (category.id === "temperature") {
    return fromCelsius(toCelsius(value, from.id), to.id);
  }
  return (value * (from.factor ?? 1)) / (to.factor ?? 1);
}

function formatNumber(value: number): string {
  if (!Number.isFinite(value)) return "—";
  const abs = Math.abs(value);
  if (abs !== 0 && (abs < 0.00001 || abs >= 1e12)) {
    return value
      .toExponential(4)
      .replace(/\.?0+e/, "e")
      .replace("e+", "e");
  }
  const digits = abs >= 100 ? 2 : abs >= 1 ? 4 : 6;
  return value.toLocaleString("en-US", { maximumFractionDigits: digits });
}

function rawNumber(value: number): string {
  return String(Number(value.toPrecision(12)));
}

type UnitSelectProps = {
  units: Unit[];
  value: string;
  onChange: (id: string) => void;
  align?: "left" | "right";
};

function UnitSelect({ units, value, onChange, align = "left" }: UnitSelectProps) {
  const [open, setOpen] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const selected = units.find((unit) => unit.id === value) ?? units[0];

  useEffect(() => {
    if (!open) return;
    const onPointer = (event: PointerEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") setOpen(false);
    };
    document.addEventListener("pointerdown", onPointer);
    document.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointer);
      document.removeEventListener("keydown", onKey);
    };
  }, [open]);

  return (
    <div ref={wrapRef} className="relative">
      <button
        type="button"
        onClick={() => setOpen((prev) => !prev)}
        aria-haspopup="listbox"
        aria-expanded={open}
        className="flex w-full items-center justify-between gap-2 rounded-xl border border-white/10 bg-white/[0.04] px-3 py-2 text-left transition hover:border-white/20 hover:bg-white/[0.07] focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-400/60"
      >
        <span className="flex min-w-0 items-baseline gap-2">
          <span className="truncate text-sm font-semibold text-white">{selected.name}</span>
          <span className="text-xs font-medium text-slate-400">{selected.symbol}</span>
        </span>
        <ChevronDown
          className={`h-4 w-4 shrink-0 text-slate-400 transition-transform duration-200 ${
            open ? "rotate-180" : ""
          }`}
        />
      </button>

      {open && (
        <div
          className={`absolute z-30 mt-2 w-full min-w-[11rem] overflow-hidden rounded-2xl border border-white/10 bg-slate-900/95 p-1 shadow-2xl shadow-black/50 backdrop-blur-xl ${
            align === "right" ? "right-0" : "left-0"
          }`}
        >
          <ul role="listbox" aria-label="Units" className="max-h-64 overflow-y-auto">
            {units.map((unit) => {
              const active = unit.id === selected.id;
              return (
                <li key={unit.id}>
                  <button
                    type="button"
                    role="option"
                    aria-selected={active}
                    onClick={() => {
                      onChange(unit.id);
                      setOpen(false);
                    }}
                    className={`flex w-full items-center justify-between gap-3 rounded-xl px-3 py-2 text-left text-sm transition ${
                      active
                        ? "bg-indigo-500/20 text-white"
                        : "text-slate-300 hover:bg-white/[0.06] hover:text-white"
                    }`}
                  >
                    <span className="flex min-w-0 items-baseline gap-2">
                      <span className="truncate font-medium">{unit.name}</span>
                      <span className="text-xs text-slate-400">{unit.symbol}</span>
                    </span>
                    {active && <Check className="h-4 w-4 shrink-0 text-indigo-300" />}
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}
    </div>
  );
}

