    setSpin((prev) => prev + 1);
    if (result !== null) {
      setInput(rawNumber(result));
      setCopied(false);
    }
  };

  const copyResult = async () => {
    if (result === null) return;
    try {
      await navigator.clipboard.writeText(`${formatNumber(result)} ${toUnit.symbol}`);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1400);
    } catch {
      /* clipboard unavailable */
    }
  };

  const recordConversion = useCallback(
    (value: number, cat: Category, from: Unit, to: Unit) => {
      const output = convert(value, cat, from, to);
      setHistory((prev) => {
        const existing = prev.find((entry) =>
          sameConversion(entry, cat.id, from, to, value)
