        );
        return [
          {
            id: existing?.id ?? `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            category: cat.id,
            from,
            to,
            input: value,
            output,
            at: Date.now(),
          },
          ...rest,
        ].slice(0, 5);
      });
    },
