  );

  useEffect(() => {
    if (!touched.current || numeric === null || fromUnit.id === toUnit.id) return;
    const generation = historyGen.current;
    const timer = window.setTimeout(() => {
      if (generation !== historyGen.current) return;
      recordConversion(numeric, category, fromUnit, toUnit);
    }, 600);
    return () => window.clearTimeout(timer);
  }, [numeric, category, fromUnit, toUnit, recordConversion]);

  const clearHistory = () => {
    historyGen.current += 1;
    setHistory([]);
  };

  return (
    <div
      className="relative min-h-screen overflow-hidden bg-slate-950 text-slate-100"
      style={{ fontFamily: '"Plus Jakarta Sans Variable", system-ui, sans-serif' }}
    >
      <div className="pointer-events-none absolute inset-0">
