{"filePath": "/app/app/sample.tsx", "content": ""use client";

import { useCallback, useEffect, useRef, useState } from "react";

const FOCUS_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;

type Mode = "focus" | "break";

function formatTime(total: number) {
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

export default function PomodoroTimer() {
  const [mode, setMode] = useState<Mode>("focus");
  const [secondsLeft, setSecondsLeft] = useState(FOCUS_SECONDS);
  const [isRunning, setIsRunning] = useState(false);
  const [completed, setCompleted] = useState(0);
  const modeRef = useRef<Mode>("focus");

  useEffect(() => {
    modeRef.current = mode;
  }, [mode]);

  const totalSeconds = mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;

  const switchMode = useCallback((next: Mode) => {
    modeRef.current = next;
    setMode(next);
    setSecondsLeft(next === "focus" ? FOCUS_SECONDS : BREAK_SECONDS);
  }, []);

  useEffect(() => {
    if (!isRunning) return;

    const id = window.setInterval(() => {
      setSecondsLeft((prev) => {
        if (prev > 1) return prev - 1;

        if (modeRef.current === "focus") {
          setCompleted((count) => count + 1);
          switchMode("break");
          return BREAK_SECONDS;
        }

        switchMode("focus");
        return FOCUS_SECONDS;
      });
    }, 1000);

    return () => window.clearInterval(id);
  }, [isRunning, switchMode]);

  const handleStartPause = () => setIsRunning((running) => !running);

  const handleReset = () => {
    setIsRunning(false);
    setSecondsLeft(mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS);
  };

  const progress = 1 - secondsLeft / totalSeconds;
  const circumference = 2 * Math.PI * 130;

  return (
    <main className="flex min-h-screen items-center justify-center bg-[#f6f1ea] px-5 py-12">
      <section className="w-full max-w-md rounded-[2.5rem] border border-white/70 bg-white/80 p-10 shadow-[0_30px_80px_-40px_rgba(80,45,30,0.45)] backdrop-blur">
        <header className="mb-8 text-center">
          <p className="text-xs font-semibold uppercase tracking-[0.35em] text-[#c06b4f]">
            Pomodoro
          </p>
          <h1 className="mt-3 text-2xl font-semibold tracking-tight text-[#2f2622]">
            {mode === "focus" ? "Time to focus" : "Take a breather"}
          </h1>
        </header>

        <div className="relative mx-auto mb-8 flex h-72 w-72 items-center justify-center">
          <svg className="absolute inset-0 -rotate-90" viewBox="0 0 300 300">
            <circle
              cx="150"
              cy="150"
              r="130"
              fill="none"
              stroke="#efe3d9"
              strokeWidth="14"
            />
            <circle
              cx="150"
              cy="150"
              r="130"
              fill="none"
              stroke={mode === "focus" ? "#e07a5f" : "#5f9e8f"}
              strokeWidth="14"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={circumference * (1 - progress)}
              className="transition-[stroke-dashoffset] duration-1000 ease-linear"
            />
          </svg>
          <div className="text-center">
            <div className="text-6xl font-semibold tabular-nums tracking-tight text-[#2f2622]">
              {formatTime(secondsLeft)}
            </div>
            <p className="mt-2 text-sm font-medium text-[#8b7a70]">
              {mode === "focus" ? "Focus session" : "Short break"}
            </p>
          </div>
        </div>

        <div className="flex items-center justify-center gap-3">
          <button
            type="button"
            onClick={handleStartPause}
            className="h-14 min-w-[10rem] rounded-full bg-[#e07a5f] text-base font-semibold text-white shadow-lg shadow-[#e07a5f]/30 transition hover:bg-[#d2694e] active:scale-[0.98]"
          >
            {isRunning ? "Pause" : "Start"}
          </button>
          <button
            type="button"
            onClick={handleReset}
            className="flex h-14 w-14 items-center justify-center rounded-full border border-[#e4d5c8] bg-white text-[#6b5a50] transition hover:border-[#d3bfae] hover:text-[#2f2622] active:scale-[0.98]"
            aria-label="Reset timer"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="h-5 w-5"
            >
              <path d="M3 12a9 9 0 1 0 3-6.7" />
              <path d="M3 4v5h5" />
            </svg>
          </button>
        </div>

        <div className="mt-10 flex items-center justify-between rounded-2xl bg-[#faf5ef] px-5 py-4">
          <span className="text-sm font-medium text-[#8b7a70]">
            Completed sessions
          </span>
          <span className="text-lg font-semibold text-[#2f2622]">
            {completed}
          </span>
        </div>
      </section>
    </main>
  );
}
"}

