"use client";

import { useCallback, useEffect, useRef, useState } from "react";

const FOCUS_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;

type Mode = "focus" | "break";

function formatTime(total: number) {
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

export default function PomodoroTimer() {
  const [mode, setMode] = useState<Mode>("focus");
  const [secondsLeft, setSecondsLeft] = useState(FOCUS_SECONDS);
  const [isRunning, setIsRunning] = useState(false);
  const [completed, setCompleted] = useState(0);
  const modeRef = useRef<Mode>("focus");

  useEffect(() => {
    modeRef.current = mode;
  }, [mode]);

  const totalSeconds = mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;

  const switchMode = useCallback((next: Mode) => {
    modeRef.current = next;
    setMode(next);
    setSecondsLeft(next === "focus" ? FOCUS_SECONDS : BREAK_SECONDS);
  }, []);

  useEffect(() => {
    if (!isRunning) return;

    const id = window.setInterval(() => {
      setSecondsLeft((prev) => {
        if (prev > 1) return prev - 1;

        if (modeRef.current === "focus") {
          setCompleted((count) => count + 1);
          switchMode("break");
          return BREAK_SECONDS;
        }

        switchMode("focus");
        return FOCUS_SECONDS;
      });
    }, 1000);

    return () => window.clearInterval(id);
  }, [isRunning, switchMode]);

  const handleStartPause = () => setIsRunning((running) => !running);

  const handleReset = () => {
    setIsRunning(false);
    setSecondsLeft(mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS);
  };

  const progress = 1 - secondsLeft / totalSeconds;
  const circumference = 2 * Math.PI * 130;

  return (
    <main className="flex min-h-screen items-center justify-center bg-[#f6f1ea] px-5 py-12">
      <section className="w-full max-w-md rounded-[2.5rem] border border-white/70 bg-white/80 p-10 shadow-[0_30px_80px_-40px_rgba(80,45,30,0.45)] backdrop-blur">
        <header className="mb-8 text-center">
          <p className="text-xs font-semibold uppercase tracking-[0.35em] text-[#c06b4f]">
            Pomodoro
          </p>
          <h1 className="mt-3 text-2xl font-semibold tracking-tight text-[#2f2622]">
            {mode === "focus" ? "Time to focus" : "Take a breather"}
          </h1>
        </header>

        <div className="relative mx-auto mb-8 flex h-72 w-72 items-center justify-center">
          <svg className="absolute inset-0 -rotate-90" viewBox="0 0 300 300">
            <circle
              cx="150"
              cy="150"
              r="130"
              fill="none"
              stroke="#efe3d9"
              strokeWidth="14"
            />
            <circle
              cx="150"
              cy="150"
              r="130"
              fill="none"
              stroke={mode === "focus" ? "#e07a5f" : "#5f9e8f"}
              strokeWidth="14"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={circumference * (1 - progress)}
              className="transition-[stroke-dashoffset] duration-1000 ease-linear"
            />
          </svg>
          <div className="text-center">
            <div className="text-6xl font-semibold tabular-nums tracking-tight text-[#2f2622]">
              {formatTime(secondsLeft)}
            </div>
            <p className="mt-2 text-sm font-medium text-[#8b7a70]">
              {mode === "focus" ? "Focus session" : "Short break"}
            </p>
          </div>
        </div>

        <div className="flex items-center justify-center gap-3">
          <button
            type="button"
            onClick={handleStartPause}
            className="h-14 min-w-[10rem] rounded-full bg-[#e07a5f] text-base font-semibold text-white shadow-lg shadow-[#e07a5f]/30 transition hover:bg-[#d2694e] active:scale-[0.98]"
          >
            {isRunning ? "Pause" : "Start"}
          </button>
          <button
            type="button"
            onClick={handleReset}
            className="flex h-14 w-14 items-center justify-center rounded-full border border-[#e4d5c8] bg-white text-[#6b5a50] transition hover:border-[#d3bfae] hover:text-[#2f2622] active:scale-[0.98]"
            aria-label="Reset timer"
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
              className="h-5 w-5"
            >
              <path d="M3 12a9 9 0 1 0 3-6.7" />
              <path d="M3 4v5h5" />
            </svg>
          </button>
        </div>

        <div className="mt-10 flex items-center justify-between rounded-2xl bg-[#faf5ef] px-5 py-4">
          <span className="text-sm font-medium text-[#8b7a70]">
            Completed sessions
          </span>
          <span className="text-lg font-semibold text-[#2f2622]">
            {completed}
          </span>
        </div>
      </section>
    </main>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

const FOCUS_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;
const TOTAL_SESSIONS = 4;

type Mode = "focus" | "break";

function formatTime(total: number) {
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

export default function PomodoroTimer() {
  const [mode, setMode] = useState<Mode>("focus");
  const [secondsLeft, setSecondsLeft] = useState(FOCUS_SECONDS);
  const [isRunning, setIsRunning] = useState(false);
  const [completed, setCompleted] = useState(0);
  const [phaseKey, setPhaseKey] = useState(0);

  const endTimeRef = useRef<number | null>(null);
  const modeRef = useRef<Mode>("focus");
  const runningRef = useRef(false);

  const totalSeconds = mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
  const isFocus = mode === "focus";
  const progress = 1 - secondsLeft / totalSeconds;
  const circumference = 2 * Math.PI * 132;
  const completedInCycle = completed % TOTAL_SESSIONS;

  const playChime = useCallback(() => {
    try {
      const AudioCtor =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext?: typeof AudioContext })
          .webkitAudioContext;
      if (!AudioCtor) return;

      const ctx = new AudioCtor();
      const start = ctx.currentTime;
      [523.25, 659.25].forEach((frequency, index) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const at = start + index * 0.16;
        osc.type = "sine";
        osc.frequency.value = frequency;
        gain.gain.setValueAtTime(0.0001, at);
        gain.gain.exponentialRampToValueAtTime(0.12, at + 0.03);
        gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.38);
        osc.connect(gain).connect(ctx.destination);
        osc.start(at);
        osc.stop(at + 0.42);
      });
      window.setTimeout(() => {
        void ctx.close();
      }, 1000);
    } catch {
      /* audio is a nice-to-have */
    }
  }, []);

  const goToMode = useCallback(
    (next: Mode, autoplay: boolean) => {
      const nextTotal = next === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
      modeRef.current = next;
      runningRef.current = autoplay;
      endTimeRef.current = autoplay ? Date.now() + nextTotal * 1000 : null;
      setMode(next);
      setSecondsLeft(nextTotal);
      setIsRunning(autoplay);
      setPhaseKey((key) => key + 1);
      playChime();
    },
    [playChime],
  );

  const finishPhase = useCallback(() => {
    if (modeRef.current === "focus") {
      setCompleted((count) => count + 1);
      goToMode("break", true);
    } else {
      goToMode("focus", false);
    }
  }, [goToMode]);

  useEffect(() => {
    if (!isRunning) return;

    const id = window.setInterval(() => {
      const end = endTimeRef.current;
      if (end === null) return;

      const remaining = Math.max(0, Math.ceil((end - Date.now()) / 1000));
      setSecondsLeft(remaining);

      if (remaining <= 0) {
        endTimeRef.current = null;
        finishPhase();
      }
    }, 200);

    return () => window.clearInterval(id);
  }, [isRunning, finishPhase]);

  const toggleRunning = useCallback(() => {
    if (runningRef.current) {
      const end = endTimeRef.current ?? Date.now() + secondsLeft * 1000;
      endTimeRef.current = null;
      runningRef.current = false;
      setSecondsLeft(Math.max(0, Math.ceil((end - Date.now()) / 1000)));
      setIsRunning(false);
    } else {
      endTimeRef.current = Date.now() + secondsLeft * 1000;
      runningRef.current = true;
      setIsRunning(true);
    }
  }, [secondsLeft]);

  const reset = useCallback(() => {
    const total = modeRef.current === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
    endTimeRef.current = null;
    runningRef.current = false;
    setSecondsLeft(total);
    setIsRunning(false);
    setPhaseKey((key) => key + 1);
  }, []);

  const selectMode = useCallback(
    (next: Mode) => {
      if (next === modeRef.current) return;
      goToMode(next, false);
    },
    [goToMode],
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const tag = (event.target as HTMLElement | null)?.tagName;
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return;

      if (event.code === "Space") {
        event.preventDefault();
        toggleRunning();
      } else if (event.key === "r" || event.key === "R") {
        event.preventDefault();
        reset();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [toggleRunning, reset]);

  useEffect(() => {
    document.title = `${formatTime(secondsLeft)} · ${
      isFocus ? "Focus" : "Break"
    } | Pomodoro`;
  }, [secondsLeft, isFocus]);

  const statusText = isRunning
    ? isFocus
      ? "Stay with it. One task at a time."
      : "Step away and breathe."
    : secondsLeft === totalSeconds
      ? isFocus
        ? "Ready when you are."
        : "Break time, whenever you need it."
      : "Paused. Pick up where you left off.";

  return (
    <main className="relative flex min-h-screen items-center justify-center overflow-hidden bg-[#f7f1e9] px-4 py-10 text-[#2f2622] antialiased sm:px-6">
      <style>{`
        @keyframes phase-rise {
          from { opacity: 0; transform: translateY(10px) scale(0.98); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes soft-float {
          0%, 100% { transform: translate3d(0, 0, 0); }
          50% { transform: translate3d(0, -18px, 0); }
        }
        .phase-rise { animation: phase-rise 600ms cubic-bezier(0.22, 1, 0.36, 1); }
        .soft-float { animation: soft-float 14s ease-in-out infinite; }
        @media (prefers-reduced-motion: reduce) {
          .phase-rise, .soft-float { animation: none; }
        }
      `}</style>

      <div aria-hidden className="pointer-events-none absolute inset-0 overflow-hidden">
        <div
          className={`soft-float absolute -left-28 top-[-12%] h-80 w-80 rounded-full blur-3xl ${
            isFocus ? "bg-[#f2c6b3]/60" : "bg-[#bcdcd2]/60"
          }`}
        />
        <div
          className={`soft-float absolute -right-24 bottom-[-16%] h-[22rem] w-[22rem] rounded-full blur-3xl ${
            isFocus ? "bg-[#eed3bd]/60" : "bg-[#cfe3d9]/60"
          }`}
          style={{ animationDelay: "-6s" }}
        />
      </div>

      <section className="phase-rise relative w-full max-w-[27rem] overflow-hidden rounded-[2.75rem] border border-white/70 bg-white/80 p-6 shadow-[0_40px_100px_-45px_rgba(74,47,35,0.55)] backdrop-blur-xl sm:p-9">
        <div
          aria-hidden
          className="pointer-events-none absolute inset-x-10 top-0 h-px bg-gradient-to-r from-transparent via-white to-transparent"
        />

        <header className="flex items-start justify-between gap-4">
          <div className="flex items-center gap-3">
            <span
              className={`flex h-11 w-11 items-center justify-center rounded-2xl ${
                isFocus
                  ? "bg-[#e07a5f]/10 text-[#d2664c]"
                  : "bg-[#4f8f80]/10 text-[#417a6d]"
              }`}
            >
              <svg
                viewBox="0 0 24 24"
                className="h-5 w-5"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.8"
                strokeLinecap="round"
                strokeLinejoin="round"
                aria-hidden
              >
