"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

const FOCUS_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;
const TOTAL_SESSIONS = 4;

type Mode = "focus" | "break";

function formatTime(total: number) {...}

export default function PomodoroTimer() {
  const [mode, setMode] = useState<Mode>("focus");
  const [secondsLeft, setSecondsLeft] = useState(FOCUS_SECONDS);
  const [isRunning, setIsRunning] = useState(false);
  const [completed, setCompleted] = useState(0);
  const [phaseKey, setPhaseKey] = useState(0); // animation key

  const endTimeRef = useRef<number | null>(null);
  const modeRef = useRef<Mode>("focus");
  const runningRef = useRef(false);

  const totalSeconds = mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;

  const playChime = useCallback(() => { ... }, []);

  const goToMode = useCallback((next: Mode, autoplay: boolean) => {
    modeRef.current = next;
    setMode(next);
    const nextTotal = next === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
    setSecondsLeft(nextTotal);
    setPhaseKey(k => k+1);
    runningRef.current = autoplay;
    setIsRunning(autoplay);
    endTimeRef.current = autoplay ? Date.now() + nextTotal*1000 : null;
    playChime();
  }, [playChime]);

  const finishPhase = useCallback(() => {
    if (modeRef.current === "focus") {
      setCompleted(c => c+1);
      goToMode("break", true);
    } else {
      goToMode("focus", false);
    }
  }, [goToMode]);

  // tick
  useEffect(() => {
    if (!isRunning) return;
    if (endTimeRef.current === null) endTimeRef.current = Date.now() + secondsLeft*1000;
    const id = window.setInterval(() => {
      const end = endTimeRef.current;
      if (end === null) return;
      const remaining = Math.max(0, Math.ceil((end - Date.now())/1000));
      setSecondsLeft(remaining);
      if (remaining <= 0) {
        endTimeRef.current = null;
        finishPhase();
      }
    }, 200);
    return () => clearInterval(id);
  }, [isRunning, finishPhase]); // secondsLeft intentionally not dep to avoid resetting interval
```
