"use client";

import { useCallback, useEffect, useRef, useState } from "react";

const FOCUS_SECONDS = 25 * 60;
const BREAK_SECONDS = 5 * 60;
const TOTAL_SESSIONS = 4;

type Mode = "focus" | "break";

function formatTime(total: number) {
  const minutes = Math.floor(total / 60);
  const seconds = total % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

export default function PomodoroTimer() {
  const [mode, setMode] = useState<Mode>("focus");
  const [secondsLeft, setSecondsLeft] = useState(FOCUS_SECONDS);
  const [isRunning, setIsRunning] = useState(false);
  const [completed, setCompleted] = useState(0);
  const [phaseKey, setPhaseKey] = useState(0);

  const endTimeRef = useRef<number | null>(null);
  const modeRef = useRef<Mode>("focus");
  const runningRef = useRef(false);

  const totalSeconds = mode === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
  const isFocus = mode === "focus";
  const progress = 1 - secondsLeft / totalSeconds;
  const circumference = 2 * Math.PI * 132;
  const completedInCycle = completed % TOTAL_SESSIONS;

  const playChime = useCallback(() => {
    try {
      const AudioCtor =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext?: typeof AudioContext })
          .webkitAudioContext;
      if (!AudioCtor) return;

      const ctx = new AudioCtor();
      const start = ctx.currentTime;
      [523.25, 659.25].forEach((frequency, index) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const at = start + index * 0.16;
        osc.type = "sine";
        osc.frequency.value = frequency;
        gain.gain.setValueAtTime(0.0001, at);
        gain.gain.exponentialRampToValueAtTime(0.12, at + 0.03);
        gain.gain.exponentialRampToValueAtTime(0.0001, at + 0.38);
        osc.connect(gain).connect(ctx.destination);
        osc.start(at);
        osc.stop(at + 0.42);
      });
      window.setTimeout(() => {
        void ctx.close();
      }, 1000);
    } catch {
      /* audio is a nice-to-have */
    }
  }, []);

  const goToMode = useCallback(
    (next: Mode, autoplay: boolean) => {
      const nextTotal = next === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
      modeRef.current = next;
      runningRef.current = autoplay;
      endTimeRef.current = autoplay ? Date.now() + nextTotal * 1000 : null;
      setMode(next);
      setSecondsLeft(nextTotal);
      setIsRunning(autoplay);
      setPhaseKey((key) => key + 1);
      playChime();
    },
    [playChime],
  );

  const finishPhase = useCallback(() => {
    if (modeRef.current === "focus") {
      setCompleted((count) => count + 1);
      goToMode("break", true);
    } else {
      goToMode("focus", false);
    }
  }, [goToMode]);

  useEffect(() => {
    if (!isRunning) return;

    const id = window.setInterval(() => {
      const end = endTimeRef.current;
      if (end === null) return;

      const remaining = Math.max(0, Math.ceil((end - Date.now()) / 1000));
      setSecondsLeft(remaining);

      if (remaining <= 0) {
        endTimeRef.current = null;
        finishPhase();
      }
    }, 200);

    return () => window.clearInterval(id);
  }, [isRunning, finishPhase]);

  const startTimer = useCallback(() => {
    if (runningRef.current) return;
    endTimeRef.current = Date.now() + secondsLeft * 1000;
    runningRef.current = true;
    setIsRunning(true);
  }, [secondsLeft]);

  const pauseTimer = useCallback(() => {
    if (!runningRef.current) return;

    const end = endTimeRef.current ?? Date.now() + secondsLeft * 1000;
    const remaining = Math.max(0, Math.ceil((end - Date.now()) / 1000));
    endTimeRef.current = null;
    runningRef.current = false;
    setIsRunning(false);

    if (remaining <= 0) {
      finishPhase();
      return;
    }

    setSecondsLeft(remaining);
  }, [secondsLeft, finishPhase]);

  const toggleRunning = useCallback(() => {
    if (runningRef.current) {
      pauseTimer();
    } else {
      startTimer();
    }
  }, [pauseTimer, startTimer]);

  const reset = useCallback(() => {
    const total = modeRef.current === "focus" ? FOCUS_SECONDS : BREAK_SECONDS;
    endTimeRef.current = null;
    runningRef.current = false;
    setSecondsLeft(total);
    setIsRunning(false);
    setPhaseKey((key) => key + 1);
  }, []);

  const selectMode = useCallback(
    (next: Mode) => {
      if (next === modeRef.current) return;
      goToMode(next, false);
    },
    [goToMode],
  );

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const tag = (event.target as HTMLElement | null)?.tagName;
      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return;

      if (event.code === "Space") {
        event.preventDefault();
        toggleRunning();
      } else if (event.key === "r" || event.key === "R") {
        event.preventDefault();
        reset();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [toggleRunning, reset]);

  useEffect(() => {
    document.title = `${formatTime(secondsLeft)} · ${
      isFocus ? "Focus" : "Break"
    } | Pomodoro`;
  }, [secondsLeft, isFocus]);

  const statusText = isRunning
    ? isFocus
      ? "Stay with it. One task at a time."
      : "Step away and breathe."
    : secondsLeft === totalSeconds
      ? isFocus
        ? "Ready when you are."
        : "Break time, whenever you need it."
      : "Paused. Pick up where you left off.";

  return (
    <main className="relative flex min-h-screen items-center justify-center overflow-hidden bg-[#f7f1e9] px-4 py-10 text-[#2f2622] antialiased sm:px-6">
      <style>{`
        @keyframes phase-rise {
          from { opacity: 0; transform: translateY(10px) scale(0.98); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes soft-float {
          0%, 100% { transform: translate3d(0, 0, 0); }
          50% { transform: translate3d(0, -18px, 0); }
        }
        .phase-rise { animation: phase-rise 600ms cubic-bezier(0.22, 1, 0.36, 1); }
        .soft-float { animation: soft-float 14s ease-in-out infinite; }
        @media (prefers-reduced-motion: reduce) {
          .phase-rise, .soft-float { animation: none; }
        }
      `}</style>

      <div aria-hidden className="pointer-events-none absolute inset-0 overflow-hidden">
        <div
          className={`soft-float absolute -left-28 top-[-12%] h-80 w-80 rounded-full blur-3xl ${
            isFocus ? "bg-[#f2c6b3]/60" : "bg-[#bcdcd2]/60"
          }`}
        />
        <div
          className={`soft-float absolute -right-24 bottom-[-16%] h-[22rem] w-[22rem] rounded-full blur-3xl ${
