<script>
(function () {
  var PRICES = {
    free: { monthly: 0, yearly: 0 },
    pro:  { monthly: 8, yearly: 6.4 },
    team: { monthly: 15, yearly: 12 }
  };

  var buttons = document.querySelectorAll('.toggle button[data-period]');
  var cards = document.querySelectorAll('.plan[data-plan]');
  var period = 'monthly';

  function money(n) {
    return '$' + (Number.isInteger(n) ? n : n.toFixed(2).replace(/\.?0+$/, ''));
  }

  function billedNote(key, p) {
    if (key === 'free') return 'Free forever';
    if (p === 'monthly') return 'Billed monthly';
    var annual = PRICES[key].yearly * 12;
    var saved = PRICES[key].monthly * 12 - annual;
    return 'Billed ' + money(annual) + ' yearly <strong>save ' + money(saved) + '</strong>';
  }

  function render() {
    buttons.forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.dataset.period === period));
    });
    cards.forEach(function (card) {
      var key = card.dataset.plan;
      var p = PRICES[key][period];
      var amount = card.querySelector('[data-amount]');
      var billed = card.querySelector('[data-billed]');
      amount.textContent = key === 'free' ? '$0' : money(p);
      billed.innerHTML = billedNote(key, period);
      var per = card.querySelector('.per');
      if (key === 'team') per.textContent = period === 'monthly' ? '/ user / mo' : '/ user / mo';
      else per.textContent = '/ month';
    });
  }

  buttons.forEach(function (b) {
    b.addEventListener('click', function () {
      if (period === b.dataset.period) return;
      period = b.dataset.period;
      render();
    });
  });

  render();
})();
</script>
</body>
</html>
